import { DIRECTIONS, RARITY_INFOS, getDirection } from './gachaData';
import type { GachaResult, GachaState, WorldbookEntrySummary, WorldbookSnapshot } from './types';

const REGEX_HIDE_RESULT_ID = 'gacha-system-hide-result';
const REGEX_HIDE_REQUEST_ID = 'gacha-system-hide-request';
const REGEX_HIDE_PLACEHOLDER_ID = 'gacha-system-hide-placeholder';
const RUNTIME_PROMPT_ID = 'gacha-system-runtime-reminder';

function getCharacterFallbackName(): string {
  return getCurrentCharacterName() || '当前角色';
}

function summarizeEntry(entry: WorldbookEntry): WorldbookEntrySummary {
  return {
    uid: entry.uid,
    name: entry.name || `未命名条目 ${entry.uid}`,
    enabled: entry.enabled,
    strategyType: entry.strategy?.type ?? 'unknown',
    scanDepth: String(entry.strategy?.scan_depth ?? 'same_as_global'),
    keys: (entry.strategy?.keys ?? []).map(key => String(key)),
    secondaryLogic: String(entry.strategy?.keys_secondary?.logic ?? 'unknown'),
    secondaryKeys: (entry.strategy?.keys_secondary?.keys ?? []).map(key => String(key)),
    positionType: entry.position?.type ?? 'unknown',
    role: entry.position?.role ?? 'system',
    depth: entry.position?.depth ?? 0,
    order: entry.position?.order ?? 0,
    probability: entry.probability ?? 100,
    contentLength: entry.content?.length ?? 0,
    preventIncoming: Boolean(entry.recursion?.prevent_incoming),
    preventOutgoing: Boolean(entry.recursion?.prevent_outgoing),
    recursionDelayUntil: entry.recursion?.delay_until ?? null,
    sticky: entry.effect?.sticky ?? null,
    cooldown: entry.effect?.cooldown ?? null,
    delay: entry.effect?.delay ?? null,
  };
}

export async function ensureCharacterWorldbook(): Promise<string> {
  const charWorldbooks = getCharWorldbookNames('current');
  const existing = new Set(getWorldbookNames());
  if (charWorldbooks.primary && existing.has(charWorldbooks.primary)) {
    return charWorldbooks.primary;
  }

  const characterName = getCharacterFallbackName();
  const target = existing.has(characterName) ? characterName : `${characterName}_抽卡系统`;
  if (!existing.has(target)) {
    await createWorldbook(target, []);
  }
  await rebindCharWorldbooks('current', {
    primary: target,
    additional: charWorldbooks.additional.filter(name => name !== target),
  });
  return target;
}

export async function getBoundWorldbookSnapshot(): Promise<WorldbookSnapshot> {
  const targetWorldbook = await ensureCharacterWorldbook();
  const entries = await getWorldbook(targetWorldbook);
  return {
    targetWorldbook,
    entries: entries.map(summarizeEntry),
  };
}

export async function installGachaRegexes(): Promise<void> {
  await updateTavernRegexesWith(
    regexes => {
      const next = regexes.filter(
        regex =>
          regex.id !== REGEX_HIDE_RESULT_ID &&
          regex.id !== REGEX_HIDE_REQUEST_ID &&
          regex.id !== REGEX_HIDE_PLACEHOLDER_ID,
      );
      next.push(
        {
          id: REGEX_HIDE_RESULT_ID,
          script_name: '抽卡系统-隐藏抽卡结果原文',
          enabled: true,
          scope: 'character',
          find_regex: '<抽卡结果[\\s\\S]*?<\\/抽卡结果>',
          replace_string: '',
          trim_strings: '',
          source: {
            user_input: true,
            ai_output: true,
            slash_command: true,
            world_info: true,
          },
          destination: {
            display: true,
            prompt: false,
          },
          run_on_edit: true,
          min_depth: null,
          max_depth: null,
        },
        {
          id: REGEX_HIDE_REQUEST_ID,
          script_name: '抽卡系统-隐藏抽卡请求原文',
          enabled: true,
          scope: 'character',
          find_regex: '<抽卡请求[\\s\\S]*?<\\/抽卡请求>',
          replace_string: '',
          trim_strings: '',
          source: {
            user_input: true,
            ai_output: true,
            slash_command: true,
            world_info: true,
          },
          destination: {
            display: true,
            prompt: false,
          },
          run_on_edit: true,
          min_depth: null,
          max_depth: null,
        },
        {
          id: REGEX_HIDE_PLACEHOLDER_ID,
          script_name: '抽卡系统-隐藏开场暗号',
          enabled: true,
          scope: 'character',
          find_regex: '<\\s*小索今天(?:吃饭|吃)了吗\\s*>',
          replace_string: '',
          trim_strings: '',
          source: {
            user_input: true,
            ai_output: true,
            slash_command: true,
            world_info: true,
          },
          destination: {
            display: true,
            prompt: false,
          },
          run_on_edit: true,
          min_depth: null,
          max_depth: null,
        },
      );
      return next;
    },
    { scope: 'character' },
  );
}

export function buildRuntimeReminder(state: GachaState): string {
  const direction = getDirection(state.directionId);
  const result = state.activeResult;
  const now = Date.now();
  const resultLines =
    result && result.expiresAt > now
      ? [
          `当前激活人物：${result.displayName}`,
          result.realAnchor ? `现实锚点：${result.realAnchor}` : '',
          `稀有度：${result.rarity}`,
          `剩余时间约：${Math.max(0, Math.ceil((result.expiresAt - now) / 60000))}分钟`,
          `雷达：${Object.entries(result.radar)
            .map(([name, value]) => `${name}${value}`)
            .join(' / ')}`,
          `执行重点：${result.buffNote || result.commentary}`,
        ].filter(Boolean)
      : ['当前没有有效激活人物。'];

  return [
    '<抽卡系统_本轮规则>',
    `当前方向：${direction.name}`,
    `进度：${Math.floor(state.progress.points)}/100；可用抽数：${state.progress.tickets}；已触发抽卡：${state.progress.totalDrawRequests}`,
    ...resultLines,
    '未看见<抽卡请求>时，不主动开奖，不新增人物时期卡。',
    '看见<抽卡请求>时，本轮只写抽卡启动、卡面揭示、30分钟映射刚刚上身，以及眼前一个可继续操作的局面；不要直接写完整场比赛、整段演出、整次考试或整个事件的结局。',
    '抽卡后必须把爽点留给后续剧情发挥，停在{{user}}准备打出第一波操作、第一句台词、第一次反击或下一次关键选择之前后，不要一口气跳到胜利、失败、结算、赛后或休息。',
    '抽到的是人物时期、队伍体系、作品状态或名场面节点，持续30分钟；不召唤本人，不继承人格、记忆、社会关系。',
    '玩家本身可以弱也可以强，但不能长期等同于明星选手；映射结束后回落到玩家自己的基础。',
    '文末的<抽卡结果>用中文逐行填写：方向、激活人物、定位、现实锚点、稀有度、持续时间、雷达、能力说明、限制、点评。',
    '雷达按当前方向的真实维度填写，同一行用分号隔开；不要保留｛｝解释，也不要写维度A/维度B。',
    '</抽卡系统_本轮规则>',
  ].join('\n');
}

export function refreshRuntimeInjection(state: GachaState): void {
  uninjectPrompts([RUNTIME_PROMPT_ID]);
  injectPrompts([
    {
      id: RUNTIME_PROMPT_ID,
      position: 'in_chat',
      depth: 0,
      role: 'system',
      content: buildRuntimeReminder(state),
      should_scan: true,
    },
  ]);
}

export function clearRuntimeInjection(): void {
  uninjectPrompts([RUNTIME_PROMPT_ID]);
}

export function listDirectionNames(): string {
  return DIRECTIONS.map(direction => direction.name).join('、');
}

export function resultRarityColor(result?: GachaResult): string {
  const key = String(result?.rarity || '').toUpperCase();
  return RARITY_INFOS[key as keyof typeof RARITY_INFOS]?.color ?? '#94a3b8';
}
