const MAX_SERIALIZED_WORLDBOOK_LENGTH = 90000;
const OPENING_PLACEHOLDER = '<小索今天吃饭了吗>';
const OPENING_PLACEHOLDER_REGEX = /<\s*小索今天(?:吃饭|吃)了吗\s*>/;

type SerializedWorldbook = {
  text: string;
  entryCount: number;
  truncated: boolean;
};

function trimString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value.trim() : fallback;
}

function stripJsonFence(text: string): string {
  return text
    .trim()
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();
}

function extractJsonObject(text: string): Record<string, unknown> {
  const stripped = stripJsonFence(text);
  const start = stripped.indexOf('{');
  const end = stripped.lastIndexOf('}');
  if (start < 0 || end <= start) {
    throw new Error('AI 没有返回 JSON 对象');
  }
  const candidate = stripped.slice(start, end + 1);
  return JSON.parse(jsonrepair(candidate)) as Record<string, unknown>;
}

function stripOpeningScaffold(text: string): string {
  return text
    .trim()
    .replace(/^```(?:text|markdown)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .replace(/^(?:正式)?开场白[:：]\s*/i, '')
    .trim();
}

function stripTextFence(text: string): string {
  return text
    .trim()
    .replace(/^```(?:text|markdown)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function clipReference(text: string, maxLength: number): string {
  const trimmed = text.trim();
  if (trimmed.length <= maxLength) return trimmed;
  return `${trimmed.slice(0, maxLength)}\n\n[后续内容省略，按以上格式与原则继续。]`;
}

function extractMixedCharacterName(text: string, fallback: string): string {
  const heading = text.match(/^=+\s*([^=\n]+?)\s*·\s*混色人设\s*=+/m);
  if (heading?.[1]?.trim()) return heading[1].trim();
  const plainTag = text.match(/<([^<>\n]+)>/i);
  if (plainTag?.[1]?.trim() && !plainTag[1].includes('_')) return plainTag[1].trim();
  const tag = text.match(/<([^<>\n]+)_id2>/i);
  if (tag?.[1]?.trim()) return tag[1].trim();
  return fallback.trim() || '开场搭戏角色';
}

function unwrapCharacterBlock(text: string): string {
  const trimmed = stripTextFence(text);
  const match = trimmed.match(/^<[^<>\n]+(?:_id2)?>\s*([\s\S]*?)\s*<\/[^<>\n]+(?:_id2)?>$/i);
  return (match?.[1] ?? trimmed).trim();
}

function serializeEntry(entry: WorldbookEntry, index: number): string {
  const strategy = entry.strategy ?? { type: 'unknown', keys: [], scan_depth: 'unknown' };
  const secondary = strategy.keys_secondary ?? { logic: 'unknown', keys: [] };
  const position = entry.position ?? { type: 'unknown', role: 'system', depth: 0, order: 0 };
  const recursion = entry.recursion ?? { prevent_incoming: false, prevent_outgoing: false, delay_until: null };
  const effect = entry.effect ?? { sticky: null, cooldown: null, delay: null };
  return [
    `#${index + 1} ${entry.name || `未命名条目${index + 1}`}`,
    `uid: ${entry.uid}`,
    `enabled: ${entry.enabled}`,
    `strategy: ${strategy.type}, scan_depth=${strategy.scan_depth}`,
    `secondary_keys: logic=${secondary.logic}, keys=${secondary.keys.map(String).join(' / ') || '无'}`,
    `position: ${position.type}, role=${position.role}, depth=${position.depth}, order=${position.order}`,
    `probability: ${entry.probability}`,
    `recursion: prevent_incoming=${recursion.prevent_incoming}, prevent_outgoing=${recursion.prevent_outgoing}, delay_until=${recursion.delay_until}`,
    `effect: sticky=${effect.sticky}, cooldown=${effect.cooldown}, delay=${effect.delay}`,
    `keys: ${strategy.keys.map(String).join(' / ') || '无'}`,
    'content:',
    entry.content || '',
  ].join('\n');
}

function serializeWorldbook(entries: WorldbookEntry[]): SerializedWorldbook {
  let text = '';
  let truncated = false;
  for (const [index, entry] of entries.entries()) {
    const part = `${serializeEntry(entry, index)}\n\n---\n\n`;
    if (text.length + part.length > MAX_SERIALIZED_WORLDBOOK_LENGTH) {
      truncated = true;
      text += `\n[后续 ${entries.length - index} 个条目因上下文长度被截断；请优先依据已读取内容提取用户指定角色。]\n`;
      break;
    }
    text += part;
  }
  return { text, entryCount: entries.length, truncated };
}

function attrValue(block: string, name: string): string {
  const match = block.match(new RegExp(`${name}=["']([^"']+)["']`, 'i'));
  return match?.[1]?.trim() ?? '';
}

function readField(block: string, labels: string[]): string {
  for (const label of labels) {
    const match = block.match(new RegExp(`^\\s*${label}\\s*[:：|]\\s*(.+)$`, 'im'));
    if (match?.[1]) return match[1].trim();
  }
  return '';
}

function parseTimestamp(value: string, fallback: number): number {
  if (!value) return fallback;
  const numeric = Number(value.replace(/[^\d]/g, ''));
  if (Number.isFinite(numeric) && numeric > 100000000000) return numeric;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function parseDuration(value: string): number {
  const match = value.match(/(\d+(?:\.\d+)?)/);
  return match ? Math.max(1, Number(match[1])) : 30;
}

function parseRadar(text: string): RadarValues {
  const values: RadarValues = {};
  const normalized = text
    .replace(/[，、]/g, '；')
    .replace(/\//g, '；')
    .replace(/\n/g, '；');
  for (const part of normalized.split(/[;；]/)) {
    const match = part.match(/\s*([^:：\d]+)\s*[:：]?\s*(\d{1,3})/);
    if (!match) continue;
    values[match[1].trim()] = Math.max(0, Math.min(100, Number(match[2])));
  }
  return values;
}

function firstResultBlock(message: string): string | undefined {
  return Array.from(message.matchAll(/<抽卡结果(?:\s[^>]*)?>[\s\S]*?<\/抽卡结果>/g)).at(-1)?.[0];
}

function clampRadarValue(value: unknown): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.max(0, Math.min(100, numeric)) : 0;
}

function parseRadarValue(value: unknown): RadarValues {
  if (typeof value === 'string') return parseRadar(value);
  if (!value || typeof value !== 'object') return {};
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .map(([label, score]) => [label.trim(), clampRadarValue(score)] as const)
      .filter(([label]) => Boolean(label)),
  );
}

function readJsonString(value: Record<string, unknown>, names: string[], fallback = ''): string {
  for (const name of names) {
    const item = value[name];
    if (typeof item === 'string' && item.trim()) return item.trim();
    if (typeof item === 'number' && Number.isFinite(item)) return String(item);
  }
  return fallback;
}

function readJsonNumber(value: Record<string, unknown>, names: string[], fallback: number): number {
  for (const name of names) {
    const item = value[name];
    const numeric = typeof item === 'number' ? item : typeof item === 'string' ? Number(item) : NaN;
    if (Number.isFinite(numeric)) return numeric;
  }
  return fallback;
}

function stringifyJsonNote(value: unknown): string {
  if (Array.isArray(value)) return value.map(item => trimString(item)).filter(Boolean).join('；');
  if (typeof value === 'string') return value.trim();
  if (value && typeof value === 'object') return Object.values(value).map(item => trimString(item)).filter(Boolean).join('；');
  return '';
}

function parseJsonResultBlock(block: string, sourceMessageId: number | undefined, fallbackTime: number): GachaResult | undefined {
  let parsed: Record<string, unknown>;
  try {
    parsed = extractJsonObject(block);
  } catch {
    return undefined;
  }

  const displayName = readJsonString(parsed, ['card_name', '激活人物', 'display_name', 'name', 'real_anchor']);
  if (!displayName) return undefined;
  const realAnchor = readJsonString(parsed, ['real_anchor', '现实锚点', 'anchor', '锚点']);

  const durationMinutes = readJsonNumber(parsed, ['duration_minutes', '持续时间', 'duration'], 30);
  const startedAt = parseTimestamp(readJsonString(parsed, ['started_at', '开始时间戳', '开始时间']), fallbackTime);
  const expiresAt = parseTimestamp(
    readJsonString(parsed, ['expires_at', '结束时间戳', '结束时间']),
    startedAt + durationMinutes * 60 * 1000,
  );
  const tendencies = stringifyJsonNote(parsed.tendencies);
  const limits = stringifyJsonNote(parsed.limits);
  const afterglow = stringifyJsonNote(parsed.afterglow);

  return {
    id: attrValue(block, 'id') || readJsonString(parsed, ['id'], `result-${sourceMessageId ?? fallbackTime}`),
    directionName: readJsonString(parsed, ['direction', '方向', 'direction_name'], getDirection('lol').name),
    displayName,
    realAnchor,
    rarity: normalizeRarity(readJsonString(parsed, ['rarity', '稀有度'])),
    role: readJsonString(parsed, ['role', '定位', 'position'], realAnchor),
    radar: parseRadarValue(parsed.radar ?? parsed.雷达 ?? parsed.雷达图数据),
    commentary: readJsonString(parsed, ['commentary', '点评', 'comment'], tendencies || afterglow),
    buffNote: readJsonString(parsed, ['buff', 'ability', '能力说明'], tendencies),
    limitNote: readJsonString(parsed, ['limit', '限制'], [limits, afterglow].filter(Boolean).join('；')),
    durationMinutes,
    startedAt,
    expiresAt,
    rawBlock: block,
    sourceMessageId,
  };
}

function containsOpeningPlaceholder(text: string | undefined): boolean {
  if (!text) return false;
  return OPENING_PLACEHOLDER_REGEX.test(text);
}

export function isOpeningPlaceholderDetected(): boolean {
  try {
    const first = getChatMessages(0)[0];
    if (!first) return false;
    return containsOpeningPlaceholder(first.message);
  } catch {
    return false;
  }
}

