export async function generateOpeningDraft(input: OpeningInput, onStream: (text: string) => void): Promise<string> {
  if (!input.state.setup.userOpeningBrief.trim()) {
    throw new Error('请先填写用户想要的开场背景');
  }

  const generationId = `gacha-opening-${Date.now()}`;
  const listener = eventOn(iframe_events.STREAM_TOKEN_RECEIVED_FULLY, (text, id) => {
    if (id === generationId) {
      onStream(stripOpeningScaffold(text));
    }
  });

  try {
    const finalText = await generateRaw({
      generation_id: generationId,
      should_stream: true,
      should_silence: false,
      max_chat_history: 0,
      ordered_prompts: [
        {
          role: 'system',
          content: [
            '你是抽卡系统开场白写作助手。你只输出正式开场白纯文本。',
            '强制底层：{{user}}穿越到一个与现实结构高度相同的平行世界，并在用户指定背景中合理激活抽卡系统。',
            '不得修改用户想要的背景、地点、关系、事件性质。哪怕是日常场景，也可以让系统通过心跳、手机、弹窗、视野UI、旧物、直播间、社团报名表等方式自然激活。',
            '除非用户给出的场景本身是比赛、突发事件或挑衅，否则不要强行把日常改成比赛或事故。',
            '初始角色是第一个与{{user}}搭戏的人，不是玩家本人，不是抽卡人物本人。',
            '玩家可以弱也可以强，但不能一开始就等同明星选手；抽卡系统的意义是短时间拉高上限和制造逆转。',
            '不要替{{user}}做最终选择，结尾要留下可行动空间。',
            '不要输出标题、Markdown、JSON、世界书条目名或解释。',
          ].join('\n'),
        },
        {
          role: 'user',
          content: [
            `方向：${input.direction.name}`,
            `雷达维度：${input.direction.radarLabels.join(' / ')}`,
            `用户想要的开场背景：${input.state.setup.userOpeningBrief}`,
            '',
            '初始搭戏角色：',
            input.companionRewrite
              ? [
                  `姓名：${input.companionRewrite.characterName}`,
                  `身份：${input.companionRewrite.realWorldIdentity}`,
                  `与{{user}}关系：${input.companionRewrite.relationshipToUser}`,
                  `人设：${input.companionRewrite.mixedProfile}`,
                ].join('\n')
              : [
                  `姓名：${input.state.setup.requestedRoleName || '未指定'}`,
                  `身份：${input.state.setup.companionIdentity || '按用户设定'}`,
                  `与{{user}}关系：${input.state.setup.companionRelation || '按用户设定'}`,
                  '未完成世界书转写时，请只使用用户填写的信息，不要自创复杂来源设定。',
                ].join('\n'),
            '',
            '请写正式开场白。',
          ].join('\n'),
        },
      ],
    });
    const opening = stripOpeningScaffold(finalText);
    onStream(opening);
    return opening;
  } finally {
    listener.stop();
  }
}

export async function writeOpeningToFirstMessage(openingText: string): Promise<void> {
  const message = stripOpeningScaffold(openingText);
  if (!message) {
    throw new Error('开场白为空，不能写入');
  }

  const current = getChatMessages(0);
  const name = getCurrentCharacterName() || '抽卡系统';
  if (current.length > 0) {
    await setChatMessages([{ message_id: 0, role: 'assistant', name, message }], { refresh: 'affected' });
    return;
  }
  await createChatMessages([{ role: 'assistant', name, message }], { insert_before: 'end', refresh: 'affected' });
}

export function buildDrawRequestBlock(state: GachaState): string {
  const direction = getDirection(state.directionId);
  const request = {
    reason: '由当前剧情判断',
    direction: direction.name,
    scene: '由当前最新剧情判断',
    risk: '由当前剧情判断',
  };
  return ['<抽卡请求>', JSON.stringify(request, null, 2), '</抽卡请求>'].join('\n');
}

export async function appendDrawRequestToLatestMessage(requestBlock: string): Promise<boolean> {
  const latest = getChatMessages(-1)[0];
  const latestIsUser = latest?.role === 'user' || latest?.name === SillyTavern.name1;
  if (!latest || !latestIsUser) {
    await createChatMessages(
      [{ role: 'user', name: SillyTavern.name1 || '{{user}}', message: requestBlock }],
      { insert_before: 'end', refresh: 'affected' },
    );
    return true;
  }
  await setChatMessages(
    [
      {
        message_id: latest.message_id,
        message: `${latest.message || ''}\n\n${requestBlock}`,
      },
    ],
    { refresh: 'affected' },
  );
  return true;
}

