export function parseGachaResultBlock(block: string, sourceMessageId?: number): GachaResult | undefined {
  if (!block.trim()) return undefined;
  const startedFallback = Date.now();
  const jsonResult = parseJsonResultBlock(block, sourceMessageId, startedFallback);
  if (jsonResult) return jsonResult;

  const durationMinutes = parseDuration(readField(block, ['持续时间', 'duration']));
  const startedAt = parseTimestamp(readField(block, ['开始时间戳', '开始时间', 'started_at']), startedFallback);
  const expiresAt = parseTimestamp(
    readField(block, ['结束时间戳', '结束时间', 'expires_at']),
    startedAt + durationMinutes * 60 * 1000,
  );
  const displayName = readField(block, ['激活人物', '人物', '角色', 'card', 'name']);
  if (!displayName) return undefined;
  const realAnchor = readField(block, ['现实锚点', '真实锚点', '锚点', 'real_anchor', 'anchor']);

  return {
    id: attrValue(block, 'id') || `result-${sourceMessageId ?? startedFallback}`,
    directionName: readField(block, ['方向', '领域']) || getDirection('lol').name,
    displayName,
    realAnchor,
    rarity: normalizeRarity(readField(block, ['稀有度', 'rarity'])),
    role: readField(block, ['定位', '角色定位', 'role']) || realAnchor,
    radar: parseRadar(readField(block, ['雷达图数据', '雷达数据', '雷达', 'radar'])),
    commentary: readField(block, ['点评', '介绍', 'commentary']),
    buffNote: readField(block, ['能力说明', 'Buff说明', 'buff']),
    limitNote: readField(block, ['限制', 'limit']),
    durationMinutes,
    startedAt,
    expiresAt,
    rawBlock: block,
    sourceMessageId,
  };
}

export function scanRecentGachaResult(): GachaResult | undefined {
  try {
    const lastId = getLastMessageId();
    if (lastId < 0) return undefined;
    const from = Math.max(0, lastId - 12);
    const messages = getChatMessages(`${from}-${lastId}`);
    for (const message of messages.slice().reverse()) {
      const block = firstResultBlock(message.message || '');
      const parsed = block ? parseGachaResultBlock(block, message.message_id) : undefined;
      if (parsed) return parsed;
    }
  } catch {
    // Ignore scan failures; UI can continue without a captured result.
  }
  return undefined;
}

function remainingMinutesFromState(state: GachaState): number {
  const result = state.activeResult;
  if (!result) return 0;
  return Math.max(0, Math.ceil((result.expiresAt - Date.now()) / 60000));
}

export async function mirrorProgressToMvu(state: GachaState): Promise<void> {
  try {
    const data = Mvu.getMvuData({ type: 'chat' });
    data.stat_data ??= {};
    data.stat_data.抽卡进度 = Math.floor(state.progress.points);
    data.stat_data.可用抽数 = state.progress.tickets;
    data.stat_data.剩余分钟 = remainingMinutesFromState(state);
    await Mvu.replaceMvuData(data, { type: 'chat' });
  } catch {
    // ignore
  }
}

export function readProgressFromMvu(): Partial<GachaState['progress']> | undefined {
  try {
    const data = Mvu.getMvuData({ type: 'chat' });
    const progress: Partial<GachaState['progress']> = {};
    const points = Number(data.stat_data?.抽卡进度);
    const tickets = Number(data.stat_data?.可用抽数);
    if (Number.isFinite(points)) progress.points = Math.max(0, points);
    if (Number.isFinite(tickets)) progress.tickets = Math.max(0, tickets);
    return progress;
  } catch {
    return undefined;
  }
}

