BAAiB,CACjB,oBACF,CAEA,yBACE,YAAa,CACb,kCAAmC,CACnC,iBAAkB,CAClB,kCAAsC,CACtC,aACF,CAEA,+BACE,kCAAsC,CACtC,aACF,CAEA,yBACE,sCACE,yBACF,CAEA,8BACE,gBACF,CAEA,kCACE,mBACF,CAEA,wDAEE,yBACF,CAEA,oBACE,cACF,CACF","sourcesContent":["<template>\n  <section class=\"gacha-opening-stage\">\n    <div class=\"opening-art\" aria-hidden=\"true\">\n      <div class=\"art-orbit\">\n        <span>抽卡</span>\n      </div>\n    </div>\n\n    <div class=\"opening-content\">\n      <div class=\"opening-head\">\n        <span class=\"eyebrow\">抽卡系统</span>\n        <h1>开场白引导</h1>\n        <p>选方向，定角色，写第一幕。</p>\n      </div>\n\n      <div class=\"step-list\">\n        <article class=\"step-card\">\n          <div class=\"step-no\">01</div>\n          <div class=\"step-body\">\n            <h2>选择玩法方向</h2>\n            <label class=\"field\">\n              <span>方向</span>\n              <select v-model=\"store.state.directionId\" @change=\"store.confirmDirection(store.state.directionId)\">\n                <optgroup v-for=\"group in store.directionGroups\" :key=\"group.group\" :label=\"group.group\">\n                  <option v-for=\"item in group.items\" :key=\"item.id\" :value=\"item.id\">\n                    {{ item.name }}\n                  </option>\n                </optgroup>\n              </select>\n            </label>\n            <p class=\"muted\">{{ store.direction.tagline }}</p>\n          </div>\n        </article>\n\n        <article class=\"step-card\">\n          <div class=\"step-no\">02</div>\n          <div class=\"step-body\">\n            <h2>确定第一个搭戏角色</h2>\n            <div class=\"split-row\">\n              <label class=\"field\">\n                <span>来源世界书</span>\n                <select v-model=\"store.state.setup.sourceWorldbookName\" @change=\"store.save()\">\n                  <option value=\"\">选择要读取的世界书</option>\n                  <option v-for=\"name in store.sourceWorldbooks\" :key=\"name\" :value=\"name\">{{ name }}</option>\n                </select>\n              </label>\n              <label class=\"field\">\n                <span>来源角色名</span>\n                <input v-model=\"store.state.setup.requestedRoleName\" placeholder=\"例如：卫疏影\" @blur=\"store.save()\" />\n              </label>\n            </div>\n            <div class=\"split-row\">\n              <label class=\"field\">\n                <span>本世界身份</span>\n                <input v-model=\"store.state.setup.companionIdentity\" placeholder=\"例如：电竞社社长\" @blur=\"store.save()\" />\n              </label>\n              <label class=\"field\">\n                <span>与 {{ userMacro }} 的关系</span>\n                <input\n                  v-model=\"store.state.setup.companionRelation\"\n                  placeholder=\"例如：社长和社团成员的普通关系\"\n                  @blur=\"store.save()\"\n                />\n              </label>\n            </div>\n            <div class=\"mode-row\">\n              <button\n                class=\"mode-chip\"\n                :class=\"{ active: store.state.setup.rewriteMode === 'default' }\"\n                type=\"button\"\n                @click=\"store.setRewriteMode('default')\"\n              >\n                默认模式\n              </button>\n              <button\n                class=\"mode-chip\"\n                :class=\"{ active: store.state.setup.rewriteMode === 'agent' }\"\n                type=\"button\"\n                @click=\"store.setRewriteMode('agent')\"\n              >\n                Agent 模式\n              </button>\n              <span v-if=\"store.state.setup.rewriteMode === 'agent'\" class=\"warning\">会补一段剧情推动线索。</span>\n            </div>\n            <button class=\"primary-btn\" type=\"button\" :disabled=\"Boolean(store.busy)\" @click=\"store.rewriteCompanion\">\n              {{ store.busy === 'rewrite' ? '正在转写' : '转写搭戏角色' }}\n            </button>\n            <div v-if=\"store.state.companionRewrite\" class=\"preview-box\">\n              <strong>{{ store.state.companionRewrite.characterName }}</strong>\n              <span>{{ store.state.companionRewrite.realWorldIdentity }}</span>\n              <p>{{ store.state.companionRewrite.relationshipToUser }}</p>\n              <pre>{{ store.state.companionRewrite.mixedProfile }}</pre>\n            </div>\n          </div>\n        </article>\n\n        <article class=\"step-card\">\n          <div class=\"step-no\">03</div>\n          <div class=\"step-body\">\n            <h2>写第一幕</h2>\n            <label class=\"field\">\n              <span>用户想要的开场背景</span>\n              <textarea\n                v-model=\"store.state.setup.userOpeningBrief\"\n                rows=\"4\"\n                placeholder=\"写你想要的日常、比赛、社团、片场、试训等背景；开场会加入穿越与抽卡系统激活。\"\n                @blur=\"store.save()\"\n              ></textarea>\n            </label>\n            <div class=\"action-row\">\n              <button class=\"secondary-btn\" type=\"button\" :disabled=\"Boolean(store.busy)\" @click=\"store.generateOpening\">\n                {{ store.busy === 'opening' ? '生成中' : '生成开场白' }}\n              </button>\n              <button class=\"danger-btn\" type=\"button\" :disabled=\"!store.state.openingDraft?.text || Boolean(store.busy)\" @click=\"store.writeOpening\">\n                {{ store.busy === 'write-opening' ? '写入中' : '进入剧情' }}\n              </button>\n            </div>\n            <label class=\"field\">\n              <span>开场草稿，可手动修改</span>\n              <textarea\n                :value=\"store.state.openingDraft?.text || ''\"\n                rows=\"9\"\n                placeholder=\"生成后会出现在这里；可以手动修改。\"\n                @input=\"store.updateOpeningDraft(($event.target as HTMLTextAreaElement).value)\"\n              ></textarea>\n            </label>\n          </div>\n        </article>\n      </div>\n\n      <div class=\"notice\" :class=\"{ error: Boolean(store.lastError) }\">\n        {{ store.lastError || store.state.lastNotice || '等你定开场。' }}\n      </div>\n    </div>\n  </section>\n</template>\n\n<script se