import type { CompanionRewrite, Direction, WorldbookSyncResult } from './types';
import { ensureCharacterWorldbook } from './worldbook';

export const WORLDBOOK_NAME = '抽卡系统';
export const MANAGED_VERSION = 3;

const MANAGED_MARKER = 'gacha_system';

export const ALWAYS_ON_ENTRIES = new Set([
  '竞技游戏通用结构',
  '抽卡通用规则',
  '变量列表',
  '[mvu_update]变量更新规则',
  '[mvu_update]变量输出格式',
]);

function directionEntryName(name: string): string {
  return `[抽卡系统|方向|${name}]`;
}

function isCompanionEntry(entry: WorldbookEntry): boolean {
  const marker = entry.extra?.[MANAGED_MARKER];
  return (
    String(marker?.kind ?? '') === 'companion_copy' ||
    String(marker?.kind ?? '') === 'companion' ||
    entry.name?.startsWith('抽卡系统-角色-')
  );
}

function makeCharacterFallbackName(): string {
  return getCurrentCharacterName() || '当前角色';
}

function makeCharacterBlockName(characterName: string): string {
  const normalized = characterName.replace(/[<>\s]/g, '') || '开场搭戏角色';
  return normalized;
}

export function wrapAsCharacterBlock(content: string, characterName: string): string {
  const trimmed = content.trim();
  const fullBlock = trimmed.match(/^<([^<>\n]+)>\s*[\s\S]*?\s*<\/[^<>\n]+>$/i);
  if (fullBlock && !fullBlock[1].endsWith('_id2')) {
    return trimmed;
  }
  const blockName = makeCharacterBlockName(characterName);
  return [`<${blockName}>`, trimmed || `${characterName}：等待补全人设。`, `</${blockName}>`].join('\n');
}

function unwrapCharacterBlock(content: string): string {
  const trimmed = content.trim();
  const match = trimmed.match(/^<[^<>\n]+(?:_id2)?>\s*([\s\S]*?)\s*<\/[^<>\n]+(?:_id2)?>$/i);
  return (match?.[1] ?? trimmed).trim();
}

function makeCompanionEntry(name: string, content: string, order: number): PartialDeep<WorldbookEntry> {
  return {
    name,
    enabled: true,
    strategy: {
      type: 'constant',
      keys: [],
      keys_secondary: { logic: 'and_any', keys: [] },
      scan_depth: 'same_as_global',
    },
    position: {
      type: 'before_character_definition',
      role: 'system',
      depth: 0,
      order,
    },
    content,
    probability: 100,
    recursion: {
      prevent_incoming: true,
      prevent_outgoing: true,
      delay_until: null,
    },
    effect: {
      sticky: null,
      cooldown: null,
      delay: null,
    },
    extra: {
      [MANAGED_MARKER]: {
        managed: true,
        version: MANAGED_VERSION,
        kind: 'companion_copy',
      },
    },
  };
}

function cloneEntrySettings(entry: WorldbookEntry, name: string, content: string): PartialDeep<WorldbookEntry> {
  const cloned = JSON.parse(JSON.stringify(entry)) as PartialDeep<WorldbookEntry>;
  delete (cloned as { uid?: number }).uid;
  cloned.name = name;
  cloned.content = content;
  cloned.enabled = true;
  cloned.extra = {
    ...((cloned.extra as Record<string, unknown>) ?? {}),
    [MANAGED_MARKER]: {
      managed: true,
      version: MANAGED_VERSION,
      kind: 'companion_copy',
      copied_from_uid: entry.uid,
      copied_from_name: entry.name,
    },
  };
  return cloned;
}

function buildCompanionEntryContent(rewrite: CompanionRewrite): string {
  const profileText = unwrapCharacterBlock(rewrite.wrappedProfile || rewrite.mixedProfile);
  return [
    `<抽卡系统_开场搭戏角色 name="${rewrite.characterName}">`,
    `来源世界书：${rewrite.sourceWorldbook}`,
    `用户指定来源角色：${rewrite.requestedRoleName}`,
    `本世界身份：${rewrite.realWorldIdentity}`,
    `与{{user}}关系：${rewrite.relationshipToUser}`,
    '',
    wrapAsCharacterBlock(profileText, rewrite.characterName),
    '</抽卡系统_开场搭戏角色>',
  ].join('\n');
}

function makeUniqueEntryName(entries: WorldbookEntry[], baseName: string): string {
  const used = new Set(entries.map(entry => entry.name));
  if (!used.has(baseName)) return baseName;
  let index = 2;
  while (used.has(`${baseName}-${index}`)) {
    index += 1;
  }
  return `${baseName}-${index}`;
}

export async function resetNonCommonEntries(): Promise<WorldbookSyncResult> {
  const worldbooks = new Set(getWorldbookNames());
  if (!worldbooks.has(WORLDBOOK_NAME)) {
    throw new Error(`没有找到世界书：${WORLDBOOK_NAME}`);
  }

  const updated = await updateWorldbookWith(
    WORLDBOOK_NAME,
    entries =>
      entries.map(entry => {
        if (ALWAYS_ON_ENTRIES.has(entry.name)) {
          return { ...entry, enabled: true };
        }
        if (isCompanionEntry(entry)) {
          return entry;
        }
        return { ...entry, enabled: false };
      }),
    { render: 'debounced' },
  );
  return { targetWorldbook: WORLDBOOK_NAME, entryCount: updated.length };
}

export async function activateDirectionEntries(direction: Direction): Promise<WorldbookSyncResult> {
  const toEnable = new Set([
    ...direction.worldbookEntries.directionEntries.map(directionEntryName),
    ...direction.worldbookEntries.detailEntries,
  ]);

  const updated = await updateWorldbookWith(
    WORLDBOOK_NAME,
    entries =>
      entries.map(entry => {
        if (ALWAYS_ON_ENTRIES.has(entry.name) || toEnable.has(entry.name)) {
          return { ...entry, enabled: true };
        }
        if (isCompanionEntry(entry)) {
          return entry;
        }
        return { ...entry, enabled: false };
      }),
    { render: 'immediate' },
  );
  return { targetWorldbook: WORLDBOOK_NAME, entryCount: updated.filter(entry => entry.enabled).length };
}

export async function writeCompanionEntry(
  rewrite: CompanionRewrite,
  templateEntryUid?: number,
): Promise<WorldbookSyncResult> {
  const targetWorldbook = await ensureCharacterWorldbook();
  const entries = await getWorldbook(targetWorldbook);
  const content = buildCompanionEntryContent(rewrite);
  const baseName = `抽卡系统-角色-${rewrite.characterName || makeCharacterFallbackName()}`;
  const name = makeUniqueEntryName(entries, baseName);

  const template =
    entries.find(entry => entry.uid === templateEntryUid) ??
    entries.find(entry => !entry.extra?.[MANAGED_MARKER] && !entry.name?.startsWith('抽卡系统-'));
  const newEntry = template ? cloneEntrySettings(template, name, content) : makeCompanionEntry(name, content, 9320);
  await createWorldbookEntries(targetWorldbook, [newEntry], { render: 'immediate' });
  return { targetWorldbook, entryCount: 1 };
}
