function historyKey(item) {
    return item.sourceMessageId !== undefined ? `message:${item.sourceMessageId}` : `id:${item.id}`;
}
function normalizeHistory(history) {
    const seen = new Set();
    const normalized = [];
    for (const item of history ?? []) {
        if (!item?.result)
            continue;
        const sourceMessageId = item.result.sourceMessageId ?? item.sourceMessageId;
        const key = historyKey({ id: item.id, sourceMessageId });
        if (seen.has(key))
            continue;
        seen.add(key);
        normalized.push({
            ...item,
            id: item.result.id || item.id,
            result: {
                ...item.result,
                sourceMessageId,
            },
            sourceMessageId,
        });
    }
    return normalized.slice(0, 50);
}
