import { reloadOnChatChange, teleportStyle } from '@util/script';
import App from './App.vue';
import OpeningApp from './OpeningApp.vue';
import { GACHA_OPENING_WRITTEN_EVENT, hasOpeningBeenWrittenForCurrentChat } from './store';
const OPENING_HOST_ID = 'gacha-system-opening-host';
const RUNTIME_HOST_ID = 'gacha-system-runtime-host';
let openingApp = null;
let runtimeApp = null;
let $openingHost = null;
let $runtimeHost = null;
let $hiddenOpeningSource = null;
let originalOpeningDisplay;
let openingStyleDestroy = null;
let runtimeStyleDestroy = null;
async function waitMvuOrTimeout() {
    await Promise.race([waitGlobalInitialized('Mvu'), new Promise(resolve => window.setTimeout(resolve, 2500))]).catch(() => undefined);
}
function findOpeningMessage() {
    return $('#chat').children(".mes[mesid='0']").first();
}
function unmountOpening() {
    if (openingApp) {
        openingApp.unmount();
        openingApp = null;
    }
    $openingHost?.remove();
    $openingHost = null;
    if ($hiddenOpeningSource) {
        $hiddenOpeningSource.css('display', originalOpeningDisplay ?? '');
        $hiddenOpeningSource = null;
        originalOpeningDisplay = undefined;
    }
    openingStyleDestroy?.();
    openingStyleDestroy = null;
}
function unmountRuntime() {
    if (runtimeApp) {
        runtimeApp.unmount();
        runtimeApp = null;
    }
    $runtimeHost?.remove();
    $runtimeHost = null;
    runtimeStyleDestroy?.();
    runtimeStyleDestroy = null;
}
function mountOpening() {
    if (openingApp)
        return;
    const $message = findOpeningMessage();
    if ($message.length === 0)
        return;
    const $messageText = $message.find('.mes_text').first();
    if ($messageText.length === 0)
        return;
    if ($message.find(`#${OPENING_HOST_ID}`).length > 0)
        return;
    unmountRuntime();
    originalOpeningDisplay = $messageText.css('display');
    $messageText.css('display', 'none');
    $hiddenOpeningSource = $messageText;
    $openingHost = $('<div>')
        .attr({
        id: OPENING_HOST_ID,
        script_id: getScriptId(),
    })
        .insertAfter($messageText);
    openingStyleDestroy = teleportStyle().destroy;
    openingApp = createApp(OpeningApp).use(createPinia());
    openingApp.mount($openingHost[0]);
}
function mountRuntime() {
    if (runtimeApp)
        return;
    unmountOpening();
    $runtimeHost = $('<div>')
        .attr({
        id: RUNTIME_HOST_ID,
        script_id: getScriptId(),
    })
        .appendTo('body');
    runtimeStyleDestroy = teleportStyle().destroy;
    runtimeApp = createApp(App).use(createPinia());
    runtimeApp.mount($runtimeHost[0]);
}
function routeMount() {
    if (hasOpeningBeenWrittenForCurrentChat()) {
        mountRuntime();
        return;
    }
    mountOpening();
}
function scheduleRoute() {
    window.setTimeout(errorCatched(routeMount), 120);
}
function unmountAll() {
    unmountOpening();
    unmountRuntime();
}
$(() => {
    void (async () => {
        await waitMvuOrTimeout();
        scheduleRoute();
        const chatChangeHandler = reloadOnChatChange();
        eventOn('chatLoaded', () => {
            unmountAll();
            scheduleRoute();
        });
        eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, messageId => {
            if (messageId === 0 && !hasOpeningBeenWrittenForCurrentChat()) {
                unmountOpening();
                scheduleRoute();
            }
        });
        eventOn(tavern_events.MESSAGE_EDITED, messageId => {
            if (messageId === 0 && !hasOpeningBeenWrittenForCurrentChat()) {
                unmountOpening();
                scheduleRoute();
            }
        });
        window.addEventListener(GACHA_OPENING_WRITTEN_EVENT, () => {
            unmountOpening();
            scheduleRoute();
        });
        $(window).on('pagehide', () => {
            unmountAll();
            chatChangeHandler.stop();
        });
    })();
});
