ACE,gBACF,CAEA,8BACE,gBACF,CAEA,8BACE,YACF,CACF","sourcesContent":["<template>\n  <div class=\"gacha-root\">\n    <Transition name=\"gacha-fab\">\n      <button\n        v-if=\"!store.isOpen\"\n        class=\"gacha-fab-button\"\n        :class=\"[fabTier, { dragging: isFabDragging, snapped: isMobile && !isFabDragging }]\"\n        :style=\"fabStyle\"\n        title=\"抽卡系统\"\n        @pointerdown=\"onFabPointerDown\"\n      >\n        <StatusBadgeSvg :tier=\"fabTier\" />\n        <span class=\"fab-copy\">\n          <strong>抽卡系统</strong>\n          <span>{{ collapsedLine }}</span>\n        </span>\n      </button>\n    </Transition>\n\n    <Transition name=\"gacha-overlay\">\n      <div v-if=\"store.isOpen && isMobile\" class=\"gacha-overlay\" @click=\"store.isOpen = false\"></div>\n    </Transition>\n\n    <Transition :name=\"isMobile ? 'gacha-drawer' : 'gacha-panel'\">\n      <section\n        v-if=\"store.isOpen\"\n        class=\"gacha-panel\"\n        :class=\"{ drawer: isMobile, busy: Boolean(store.busy) }\"\n        :style=\"[panelStyle, panelArtStyle]\"\n      >\n        <div v-if=\"isMobile\" class=\"drawer-handle\" @pointerdown=\"onDrawerPointerDown\">\n          <span></span>\n        </div>\n\n        <header class=\"panel-head\" @pointerdown=\"!isMobile && onPanelPointerDown($event)\">\n          <div class=\"title-block\">\n            <StatusBadgeSvg :tier=\"fabTier\" compact />\n            <div>\n              <strong>抽卡系统</strong>\n              <small>{{ headerSubtitle }}</small>\n            </div>\n          </div>\n          <div class=\"head-actions\">\n            <button class=\"icon-btn\" title=\"刷新绑定世界书\" @pointerdown.stop @click=\"store.refreshTargetWorldbookSnapshot\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n                <path d=\"M21 12a9 9 0 0 1-15.4 6.4M3 12A9 9 0 0 1 18.4 5.6\" />\n                <path d=\"M21 4v6h-6M3 20v-6h6\" />\n              </svg>\n            </button>\n            <button class=\"icon-btn\" title=\"收起\" @pointerdown.stop @click=\"store.isOpen = false\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n                <path d=\"M18 6 6 18M6 6l12 12\" />\n              </svg>\n            </button>\n          </div>\n        </header>\n\n        <nav class=\"tab-strip\">\n          <button\n            v-for=\"tab in store.tabs\"\n            :key=\"tab.id\"\n            :class=\"{ active: store.activeTab === tab.id }\"\n            @click=\"store.activeTab = tab.id\"\n          >\n            {{ tab.label }}\n          </button>\n        </nav>\n\n        <main class=\"panel-body\">\n          <section v-if=\"store.activeTab === 'overview'\" class=\"view-grid\">\n            <div class=\"hero-band\">\n              <div>\n                <span class=\"eyebrow\">{{ store.direction.group }}</span>\n                <h2>{{ store.direction.name }}</h2>\n                <p>{{ store.direction.tagline }}</p>\n              </div>\n              <div class=\"hero-meter\">\n                <strong>{{ store.progressPercent }}%</strong>\n                <span>进度</span>\n              </div>\n            </div>\n\n            <div class=\"status-row\">\n              <div class=\"stat-box\">\n                <span>可用抽数</span>\n                <strong>{{ store.state.progress.tickets }}</strong>\n              </div>\n              <div class=\"stat-box\">\n                <span>累计触发</span>\n                <strong>{{ store.state.progress.totalDrawRequests }}</strong>\n              </div>\n              <div class=\"stat-box\">\n                <span>结果数</span>\n                <strong>{{ store.state.progress.totalResultsCaptured }}</strong>\n              </div>\n              <div class=\"stat-box\">\n                <span>当前映射</span>\n                <strong>{{ store.activeResultValid ? store.remainingMinutes + ' 分钟' : '无' }}</strong>\n              </div>\n            </div>\n\n            <div class=\"active-layout\">\n              <div class=\"active-card\" :class=\"activeRarityClass\">\n                <CardFrameSvg :rarity=\"activeRarity\" />\n                <span class=\"card-rarity\" :style=\"rarityStyle(activeRarity)\">{{ activeRarity || '--' }}</span>\n                <strong>{{ currentResult?.displayName || '待命中' }}</strong>\n                <small>{{ currentResult?.role || '尚未激活' }}</small>\n                <p>\n                  {{\n                    currentResult?.commentary || '等待抽卡'\n                  }}\n                </p>\n                <dl v-if=\"currentResult\" class=\"result-meta\">\n                  <div>\n                    <dt>方向</dt>\n                    <dd>{{ currentResult.directionName }}</dd>\n                  </div>\n                  <div v-if=\"currentResult.realAnchor\">\n                    <dt>锚点</dt>\n                    <dd>{{ currentResult.realAnchor }}</dd>\n                  </div>\n                  <div>\n                    <dt>说明</dt>\n                    <dd>{{ currentResult.buffNote || '等待正文补充能力映射。' }}</dd>\n                  </div>\n                  <div>\n                    <dt>限制</dt>\n                    <dd>{{ currentResult.limitNote || '过期后回落到自身能力。' }}</dd>\n                  </div>\n                </dl>\n              </div>\n              <RadarChart :labels=\"radarLabels\" :values=\"currentResult?.radar\" />\n            </div>\n\n            <div class=\"notice-line\" :class=\"{ error: Boolean(store.lastError) }\">\n              {{ store.lastError || store.state.lastNotice || '' }}\n            </div>\n          </section>\n\n          <section v-else-if=\"store.activeTab === 'worldbook'\" class=\"form-stack\">\n            <div class=\"section-headline\">\n              <div>\n                <span class=\"eyebrow\">角色世界书</span>\n                <h2>搭戏角色</h2>\n              </div>\n              <p>把开场搭戏角色写进当前角色世界书。</p>\n            </div>\n\n            <div class=\"worldbook-summary\">\n              <div>\n                <span>绑定角色世界书</span>\n                <strong>{{ store.state.targetWorldbook || '尚未读取' }}</strong>\n              </div>\n              <div>\n                <span>条目数</span>\n                <strong>{{ store.targetWorldbookEntries.length }}</strong>\n              </div>\n            </div>\n\n            <div class=\"split-row\">\n              <label class=\"field\">\n                <span>玩法方向</span>\n                <select v-model=\"store.state.directionId\" @change=\"store.confirmDirection(store.state.directionId)\">\n                  <optgroup v-for=\"group in store.directionGroups\" :key=\"group.group\" :label=\"group.group\">\n                    <option v-for=\"item in group.items\" :key=\"item.id\" :value=\"item.id\">\n                      {{ item.name }}\n                    </option>\n                  </optgroup>\n                </select>\n              </label>\n              <div class=\"direction-note\">\n                <span>{{ store.direction.group }}</span>\n                <strong>{{ store.direction.name }}</strong>\n                <p>{{ store.direction.tagline }}</p>\n              </div>\n            </div>\n\n            <div class=\"action-row\">\n              <button class=\"primary-btn\" :disabled=\"Boolean(store.busy)\" @click=\"store.refreshTargetWorldbookSnapshot\">\n                读取绑定世界书\n              </button>\n              <button class=\"ghost-btn\" :disabled=\"Boolean(store.busy)\" @click=\"store.syncWorldbookRules\">\n                刷新方向规则\n              </button>\n              <button class=\"ghost-btn\" :disabled=\"Boolean(store.busy)\" @click=\"store.installRegex\">\n                隐藏抽卡原文\n              </button>\n            </div>\n\n            <div class=\"split-row\">\n              <label class=\"field\">\n                <span>来源世界书</span>\n                <select v-model=\"store.state.setup.sourceWorldbookName\" @change=\"store.save()\">\n                  <option value=\"\">选择要读取的世界书</option>\n                  <option v-for=\"name in store.sourceWorldbooks\" :key=\"name\" :value=\"name\">{{ name }}</option>\n                </select>\n              </label>\n              <label class=\"field\">\n                <span>参考条目样式</span>\n                <select v-model.number=\"templateUidProxy\">\n                  <option :value=\"0\">自动选择一个非系统条目</option>\n                  <option v-for=\"entry in store.targetWorldbookEntries\" :key=\"entry.uid\" :value=\"entry.uid\">\n                    {{ entryTemplateLabel(entry) }}\n                  </option>\n                </select>\n              </label>\n            </div>\n\n            <div class=\"split-row\">\n              <label class=\"field\">\n                <span>来源角色名</span>\n                <input v-model=\"store.state.setup.requestedRoleName\" placeholder=\"例如：卫疏影\" @blur=\"store.save()\" />\n              </label>\n              <label class=\"field\">\n                <span>本世界身份</span>\n                <input v-model=\"store.state.setup.companionIdentity\" placeholder=\"例如：电竞社社长\" @blur=\"store.save()\" />\n              </label>\n            </div>\n\n            <label class=\"field\">\n              <span>与 {{ userMacro }} 的关系</span>\n              <input\n                v-model=\"store.state.setup.companionRelation\"\n                placeholder=\"例如：社长和社团成员的普通关系\"\n                @blur=\"store.save()\"\n              />\n            </label>\n\n            <div class=\"mode-row\">\n              <button\n                class=\"mode-chip\"\n                :class=\"{ active: store.state.setup.rewriteMode === 'default' }\"\n                @click=\"store.setRewriteMode('default')\"\n              >\n                默认模式\n              </button>\n              <button\n                class=\"mode-chip\"\n                :class=\"{ active: store.state.setup.rewriteMode === 'agent' }\"\n                @click=\"store.setRewriteMode('agent')\"\n              >\n                Agent 模式\n              </button>\n            </div>\n\n            <div class=\"action-row\">\n              <button class=\"primary-btn\" :disabled=\"Boolean(store.busy)\" @click=\"store.rewriteCompanion\">\n                转写并新增\n              </button>\n              <button class=\"danger-btn\" :disabled=\"!store.state.companionRewrite || Boolean(store.busy)\" @click=\"store.addCompanionToWorldbook\">\n                新增这个角色\n              </button>\n            </div>\n\n            <div class=\"companion-preview\">\n              <div class=\"preview-head\">\n                <strong>{{ store.state.companionRewrite?.characterName || '尚未转写角色' }}</strong>\n                <span>{{ store.state.companionRewrite?.realWorldIdentity || '等待来源世界书' }}</span>\n              </div>\n              <p>{{ store.state.companionRewrite?.relationshipToUser || '转写后会显示与玩家的关系。' }}</p>\n              <pre>{{ store.state.companionRewrite?.mixedProfile || '转写后会显示人设正文。' }}</pre>\n            </div>\n\n            <div v-if=\"store.targetWorldbookEntries.length === 0\" class=\"empty-state\">尚未读取到绑定角色世界书。</div>\n          </section>\n\n          <section v-else-if=\"store.activeTab === 'draw'\" class=\"draw-view\">\n            <div class=\"draw-console\">\n              <div class=\"progress-ring\" :style=\"{ '--progress': store.progressPercent + '%' }\">\n                <strong>{{ store.progressPercent }}</strong>\n                <span>/100</span>\n              </div>\n              <div class=\"draw-copy\">\n                <h3>{{ store.direction.name }}抽卡触发</h3>\n                <p>\n                  消耗抽数或进度后触发一次抽卡，结果由正文决定。\n                </p>\n                <label class=\"inline-toggle\">\n                  <input v-model=\"store.state.setup.writeDrawRequestToLatestMessage\" type=\"checkbox\" @change=\"store.save()\" />\n                  <span>抽卡后立刻续写</span>\n                </label>\n              </div>\n            </div>\n\n            <div class=\"action-row\">\n              <button class=\"danger-btn big\" :disabled=\"!store.canDraw || Boolean(store.busy)\" @click=\"store.requestDraw\">\n                触发抽卡\n              </button>\n              <button class=\"ghost-btn\" :disabled=\"Boolean(store.busy)\" @click=\"store.captureLatestResult\">\n                刷新结果\n              </button>\n              <button class=\"ghost-btn\" :disabled=\"!store.state.activeResult || Boolean(store.busy)\" @click=\"store.clearResult\">\n                清空总览显示\n              </button>\n            </div>\n\n            <div class=\"notice-line\">\n              {{ drawHint }}\n            </div>\n          </section>\n\n          <section v-else-if=\"store.activeTab === 'history'\" class=\"history-view\">\n            <article v-for=\"item in store.state.history\" :key=\"item.id\" class=\"history-item\">\n              <span class=\"card-rarity\" :style=\"rarityStyle(item.result.rarity)\">{{ item.result.rarity }}</span>\n              <div>\n                <strong>{{ item.result.displayName }}</strong>\n                <small>{{ formatDate(item.createdAt) }} / 楼层 {{ item.sourceMessageId ?? '--' }}</small>\n                <p>{{ item.result.commentary || item.result.buffNote || '无点评。' }}</p>\n              </div>\n            </article>\n            <div v-if=\"store.state.history.length === 0\" class=\"empty-state\">暂无抽卡记录。</div>\n          </section>\n        </main>\n\n        <div v-if=\"store.busy\" class=\"busy-mask\">\n          <span></span>\n          {{ busyLabel }}\n        </div>\n      </section>\n    </Transition>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, defineComponent, onMounted, onUnmounted, ref } from 'vue';\nimport type { PropType } from 'vue';\nimport backgroundCharacters from './assets/background-characters.png?url';\nimport { RARITY_INFOS } from './gachaData';\nimport { useGachaStore } from './store';\nimport type { RadarValues, Rarity, WorldbookEntrySummary } from './types';\n\nconst store = useGachaStore();\nconst hostWindow = window.parent;\nconst userMacro = '{{user}}';\n\nconst windowWidth = ref(hostWindow.innerWidth);\nconst visualHeight = ref(hostWindow.visualViewport?.height ?? hostWindow.innerHeight);\nconst isMobile = computed(() => windowWidth.value <= 640);\n\nconst fabPosition = ref({ x: Math.max(16, hostWindow.innerWidth - 238), y: Math.max(90, hostWindow.innerHeight - 170) });\nconst panelOffset = ref({ x: 0, y: 0 });\nconst drawerTranslateY = ref(0);\nconst isFabDragging = ref(false);\n\nlet fabStart = { x: 0, y: 0, baseX: 0, baseY: 0, moved: false };\nlet panelStart = { x: 0, y: 0, baseX: 0, baseY: 0 };\nlet drawerStartY = 0;\n\nconst currentResult = computed(() => store.state.activeResult);\nconst activeRarity = computed(() => currentResult.value?.rarity || '');\nconst activeRarityClass = computed(() => `rarity-${String(activeRarity.value || 'empty').toLowerCase()}`);\nconst radarLabels = computed(() => {\n  const resultLabels = Object.keys(currentResult.value?.radar ?? {});\n  return resultLabels.length > 0 ? resultLabels : store.direction.radarLabels;\n});\n\nconst headerSubtitle = computed(() => `${store.direction.name} / ${store.state.characterName}`);\n\nconst collapsedLine = computed(() => {\n  if (store.activeResultValid && store.state.activeResult) {\n    return `${store.state.activeResult.rarity} ${store.state.activeResult.displayName}`;\n  }\n  if (store.state.progress.tickets > 0) return `可抽 ${store.state.progress.tickets} 次`;\n  return `进度 ${store.progressPercent}%`;\n});\n\nconst fabTier = computed(() => {\n  if (store.activeResultValid) return 'tier-active';\n  if (store.state.progress.tickets > 0) return 'tier-ready';\n  if (store.progressPercent >= 70) return 'tier-high';\n  if (store.progressPercent >= 35) return 'tier-mid';\n  return 'tier-low';\n});\n\nconst busyLabel = computed(() => {\n  const labels: Record<string, string> = {\n    rewrite: '正在转写角色',\n    worldbook: '正在更新世界书',\n    regex: '正在隐藏抽卡原文',\n    opening: '正在生成开场白',\n    'write-opening': '正在写入开场白',\n    draw: '正在抽卡',\n  };\n  return labels[store.busy] ?? '处理中';\n});\n\nconst drawHint = computed(() => {\n  if (store.canDraw) return '可以抽卡';\n  return `进度不足，还需要 ${100 - store.progressPercent} 点`;\n});\n\nconst templateUidProxy = computed({\n  get: () => store.state.setup.worldbookTemplateEntryUid ?? 0,\n  set: value => {\n    store.state.setup.worldbookTemplateEntryUid = Number(value) > 0 ? Number(value) : undefined;\n    store.save();\n  },\n});\n\nconst fabStyle = computed(() => ({\n  transform: `translate3d(${fabPosition.value.x}px, ${fabPosition.value.y}px, 0)`,\n}));\n\nconst panelStyle = computed(() => {\n  if (isMobile.value) {\n    return {\n      height: `${Math.min(visualHeight.value * 0.92, visualHeight.value - 10)}px`,\n      transform: `translate3d(0, ${drawerTranslateY.value}px, 0)`,\n    };\n  }\n  return {\n    transform: `translate3d(${panelOffset.value.x}px, ${panelOffset.value.y}px, 0)`,\n  };\n});\n\nconst panelArtStyle = computed(() => ({\n  '--bg-art': `url(\"${backgroundCharacters}\")`,\n}));\n\nfunction rarityStyle(rarity?: string) {\n  const key = String(rarity || '').toUpperCase() as Rarity;\n  const info = RARITY_INFOS[key];\n  return {\n    color: info?.color ?? '#94a3b8',\n    borderColor: info?.color ?? 'rgba(148, 163, 184, 0.6)',\n    boxShadow: `0 0 22px ${info?.glow ?? 'rgba(148, 163, 184, 0.2)'}`,\n  };\n}\n\nfunction formatDate(timestamp: number): string {\n  return new Date(timestamp).toLocaleString('zh-CN', { hour12: false });\n}\n\nfunction entryTemplateLabel(entry: WorldbookEntrySummary): string {\n  return `#${entry.uid} ${entry.name} / ${entry.enabled ? '启用' : '禁用'}`;\n}\n\nfunction clampFab(): void {\n  const maxX = Math.max(8, hostWindow.innerWidth - (isMobile.value ? 126 : 218));\n  const maxY = Math.max(8, (hostWindow.visualViewport?.height ?? hostWindow.innerHeight) - 74);\n  fabPosition.value = {\n    x: Math.max(8, Math.min(maxX, fabPosition.value.x)),\n    y: Math.max(8, Math.min(maxY, fabPosition.value.y)),\n  };\n}\n\nfunction updateViewport(): void {\n  windowWidth.value = hostWindow.innerWidth;\n  visualHeight.value = hostWindow.visualViewport?.height ?? hostWindow.innerHeight;\n  clampFab();\n}\n\nfunction onFabPointerDown(event: PointerEvent): void {\n  if (event.pointerType === 'mouse' && event.button !== 0) return;\n  event.preventDefault();\n  isFabDragging.value = true;\n  fabStart = {\n    x: event.clientX,\n    y: event.clientY,\n    baseX: fabPosition.value.x,\n    baseY: fabPosition.value.y,\n    moved: false,\n  };\n  hostWindow.addEventListener('pointermove', onFabPointerMove);\n  hostWindow.addEventListener('pointerup', onFabPointerUp, { once: true });\n}\n\nfunction onFabPointerMove(event: PointerEvent): void {\n  const dx = event.clientX - fabStart.x;\n  const dy = event.clientY - fabStart.y;\n  if (Math.abs(dx) + Math.abs(dy) > 5) fabStart.moved = true;\n  fabPosition.value = {\n    x: fabStart.baseX + dx,\n    y: fabStart.baseY + dy,\n  };\n  clampFab();\n}\n\nfunction onFabPointerUp(): void {\n  hostWindow.removeEventListener('pointermove', onFabPointerMove);\n  isFabDragging.value = false;\n  if (isMobile.value) {\n    fabPosition.value.x = hostWindow.innerWidth - 126;\n    clampFab();\n  }\n  if (!fabStart.moved) {\n    store.isOpen = true;\n  }\n}\n\nfunction onPanelPointerDown(event: PointerEvent): void {\n  const target = event.target as HTMLElement;\n  if (target.closest('button, input, select, textarea, a')) return;\n  if (event.pointerType === 'mouse' && event.button !== 0) return;\n  event.preventDefault();\n  panelStart = {\n    x: event.clientX,\n    y: event.clientY,\n    baseX: panelOffset.value.x,\n    baseY: panelOffset.value.y,\n  };\n  hostWindow.addEventListener('pointermove', onPanelPointerMove);\n  hostWindow.addEventListener('pointerup', onPanelPointerUp, { once: true });\n}\n\nfunction onPanelPointerMove(event: PointerEvent): void {\n  panelOffset.value = {\n    x: panelStart.baseX + event.clientX - panelStart.x,\n    y: panelStart.baseY + event.clientY - panelStart.y,\n  };\n}\n\nfunction onPanelPointerUp(): void {\n  hostWindow.removeEventListener('pointermove', onPanelPointerMove);\n}\n\nfunction onDrawerPointerDown(event: PointerEvent): void {\n  event.preventDefault();\n  drawerStartY = event.clientY;\n  hostWindow.addEventListener('pointermove', onDrawerPointerMove);\n  hostWindow.addEventListener('pointerup', onDrawerPointerUp, { once: true });\n}\n\nfunction onDrawerPointerMove(event: PointerEvent): void {\n  drawerTranslateY.value = Math.max(0, event.clientY - drawerStartY);\n}\n\nfunction onDrawerPointerUp(): void {\n  hostWindow.removeEventListener('pointermove', onDrawerPointerMove);\n  if (drawerTranslateY.value > 120) {\n    store.isOpen = false;\n  }\n  drawerTranslateY.value = 0;\n}\n\nfunction tierPalette(tier: string) {\n  const palettes: Record<string, { main: string; accent: string; dim: string }> = {\n    'tier-active': { main: '#ff315f', accent: '#fbbf24', dim: 'rgba(255, 49, 95, 0.2)' },\n    'tier-ready': { main: '#fbbf24', accent: '#22d3ee', dim: 'rgba(251, 191, 36, 0.18)' },\n    'tier-high': { main: '#fb7185', accent: '#fbbf24', dim: 'rgba(251, 113, 133, 0.16)' },\n    'tier-mid': { main: '#22d3ee', accent: '#34d399', dim: 'rgba(34, 211, 238, 0.16)' },\n    'tier-low': { main: '#64748b', accent: '#94a3b8', dim: 'rgba(100, 116, 139, 0.16)' },\n  };\n  return palettes[tier] ?? palettes['tier-low'];\n}\n\nfunction rarityPalette(rarity?: string) {\n  const key = String(rarity || '').toUpperCase() as Rarity;\n  const info = RARITY_INFOS[key];\n  return {\n    main: info?.color ?? '#64748b',\n    accent: info?.color ?? '#94a3b8',\n    glow: info?.glow ?? 'rgba(148, 163, 184, 0.22)',\n  };\n}\n\nconst StatusBadgeSvg = defineComponent({\n  props: {\n    tier: {\n      type: String,\n      required: true,\n    },\n    compact: {\n      type: Boolean,\n      default: false,\n    },\n  },\n  setup(props) {\n    const palette = computed(() => tierPalette