const DIRECTION_ALIASES: Record<string, DirectionId> = {
  music: 'singing',
};

export function getDirection(id: DirectionId): Direction {
  const normalized = DIRECTION_ALIASES[id] ?? id;
  return DIRECTIONS.find(direction => direction.id === normalized) ?? DIRECTIONS[0];
}

export function groupDirections(): Array<{ group: string; items: Direction[] }> {
  const groups: Array<{ group: string; items: Direction[] }> = [];
  for (const direction of DIRECTIONS) {
    const existing = groups.find(item => item.group === direction.group);
    if (existing) {
      existing.items.push(direction);
    } else {
      groups.push({ group: direction.group, items: [direction] });
    }
  }
  return groups;
}

export function normalizeRarity(value: string): Rarity {
  const normalized = value.trim().toUpperCase();
  if (normalized === 'UR' || normalized === 'SSR' || normalized === 'SR' || normalized === 'R' || normalized === 'N') {
    return normalized;
  }
  return 'N';
}
